    $("#cfgBackgroundUpload")?.addEventListener("change",async e=>{const f=e.target.files&&e.target.files[0];if(!f)return;if(!/^image\/(jpeg|png|webp|avif)$/.test(f.type)){toast("اختر صورة JPG أو PNG أو WEBP أو AVIF.");e.target.value="";return;}try{let imageUrl;if(window.MamlakaCloud?.ready){imageUrl=await window.MamlakaCloud.uploadImage(f,"backgrounds");}else{if(f.size>5242880)throw new Error("الصورة أكبر من 5 ميجابايت. اضغطها أو سجّل دخول الحفظ السحابي أولًا.");imageUrl=await new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=reject;r.onload=()=>{const im=new Image();im.onerror=reject;im.onload=()=>{const scale=Math.min(1,1200/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));const ctx=c.getContext("2d");if(!ctx)return reject(new Error("تعذر تجهيز الصورة"));ctx.drawImage(im,0,0,c.width,c.height);resolve(c.toDataURL("image/jpeg",0.68));};im.src=r.result;};r.readAsDataURL(f);});}$("#cfgBackgroundImage").value=imageUrl;const saved=saveSiteSettings(false);if(!saved)throw new Error("تم رفع/تجهيز الصورة لكن تعذر تأكيد حفظ رابطها.");settingsStatus(window.MamlakaCloud?.ready?"تم رفع الخلفية إلى التخزين السحابي وحفظ رابطها ✓":"تم حفظ الخلفية على هذا الجهاز فقط. سجّل دخول الحفظ السحابي لجعلها متاحة لكل العملاء.");toast(window.MamlakaCloud?.ready?"✓ تم رفع الخلفية وحفظ رابطها سحابيًا.":"تم حفظ الخلفية محليًا؛ لم يتم رفعها للسحابة.");}catch(err){settingsStatus(err.message||"تعذر حفظ الخلفية",false);toast(err.message||"تعذر حفظ الخلفية.");}finally{e.target.value="";}});
