    $("#productForm")?.addEventListener("submit",e=>{e.preventDefault();const list=products(),id=$("#pId").value||"custom-"+Date.now(),nameAr=$("#pAr").value.trim(),nameEn=$("#pEn").value.trim();if(adminReadyProducts().some(p=>String(p.id)!==String(id)&&((nameAr&&p.nameAr?.trim().toLowerCase()===nameAr.toLowerCase())||(nameEn&&p.nameEn?.trim().toLowerCase()===nameEn.toLowerCase())))){toast("يوجد منتج بالاسم نفسه؛ راجع القائمة لتجنب التكرار.");return;}const raw=$("#pPrice").value,existing={...(baseReadyProducts.find(p=>String(p.id)===String(id))||{}),...(list.find(p=>String(p.id)===String(id))||{})},productPrices={...(existing.prices||{})};["30","50","100"].forEach(n=>{const field=$("#pPrice"+n);if(field){if(field.value==="")delete productPrices[n];else productPrices[n]=Math.max(50,Number(field.value));}});const item={...existing,prices:productPrices,id,nameAr,nameEn,brand:$("#pBrand").value.trim(),productType:$("#pType").value,gender:$("#pGender").value.trim()||"للجنسين",family:$("#pFamily").value.trim(),scentNature:$("#pNature").value.trim(),topNotes:$("#pTopNotes").value.split(",").map(x=>x.trim()).filter(Boolean),heartNotes:$("#pHeartNotes").value.split(",").map(x=>x.trim()).filter(Boolean),baseNotes:$("#pBaseNotes").value.split(",").map(x=>x.trim()).filter(Boolean),chemicalCompositionNote:$("#pChemistry").value.trim(),price:raw===""?(existing.price??null):Math.max(50,Number(raw)),image:$("#pImage").value.trim(),sourceUrl:$("#pSourceUrl").value.trim(),descriptionAr:$("#pDesc").value.trim(),available:true,needsReview:raw===""&&(existing.needsReview!==false)};const i=list.findIndex(p=>String(p.id)===String(id));if(i>=0)list[i]=item;else list.push(item);try{saveProducts(list);}catch(err){toast(err.message||"تعذر حفظ المنتج والصورة.");return;}const verified=products().find(p=>String(p.id)===String(id));if(!verified||verified.image!==item.image){toast("لم يتم تأكيد حفظ صورة المنتج. جرّب صورة أصغر أو رابط صورة مباشرًا.");return;}clearProductForm();renderAdminProducts();refreshStore();});
    $("#pImage")?.addEventListener("input",()=>showProductImage($("#pImage").value));
    $("#pImageUpload")?.addEventListener("change",async e=>{const file=e.target.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp|avif)$/.test(file.type)){toast("اختر JPG أو PNG أو WEBP أو AVIF.");e.target.value="";return;}try{let imageUrl;if(window.MamlakaCloud?.ready){imageUrl=await window.MamlakaCloud.uploadImage(file,"products");}else{if(file.size>5242880)throw new Error("الصورة أكبر من 5 ميجابايت. اضغطها أو سجّل دخول الحفظ السحابي أولًا.");imageUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const scale=Math.min(1,900/Math.max(img.width,img.height));const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext("2d");if(!ctx)return reject(new Error("تعذر تجهيز الصورة"));ctx.drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL("image/jpeg",0.72));};img.src=reader.result;};reader.readAsDataURL(file);});}$("#pImage").value=imageUrl;showProductImage(imageUrl);toast(window.MamlakaCloud?.ready?"✓ تم رفع صورة المنتج سحابيًا. اضغط حفظ المنتج لتثبيت بياناته.":"تم تجهيز الصورة محليًا؛ سجّل دخول الحفظ السحابي لرفعها للعملاء.");}catch(err){toast(err.message||"تعذر حفظ الصورة. جرّب JPG أو PNG أصغر.");}finally{e.target.value="";}});
    function showProductImage(src){const box=$("#pImagePreview");if(!box)return;const safe=String(src||"").trim();if(/^(https:\/\/|assets\/|\.\/|data:image\/)/i.test(safe)){box.innerHTML='<img alt="معاينة صورة العطر" src="'+safe.replace(/&/g,"&amp;").replace(/"/g,"&quot;")+'">';}else box.textContent="معاينة صورة العطر تظهر هنا";}
